using TMPro;
using UnityEngine;

namespace TowerLand.UI
{
    /// <summary>
    /// Look of the big cartoon titles (win screen): chunky font, a vertical gradient face, a solid extrusion built from
    /// stacked offset copies (darker towards the back), one thick even outline around all of it and a soft shadow below.
    /// Drawn back to front: dark outlined silhouette of the whole stack (back-most copy casts the shadow), the coloured
    /// stack without outline, then the outlined face.
    /// Materials and font asset are generated by <c>Tools/TowerLand/Setup Win Sequence</c>; colours are tuned here.
    /// </summary>
    [CreateAssetMenu(menuName = "TowerLand/Title Style", fileName = "TitleStyle")]
    public sealed class TitleStyle : ScriptableObject
    {
        [System.Serializable]
        public struct WordColours
        {
            public Color FaceTop;
            public Color FaceBottom;
            [Tooltip("Extrusion just behind the face, and at the back.")]
            public Color ExtrudeFront;
            public Color ExtrudeBack;
        }

        [SerializeField] private TMP_FontAsset _font;
        [Tooltip("Face: outline, no shadow.")]
        [SerializeField] private Material _faceMaterial;
        [Tooltip("Coloured extrusion copies: no outline.")]
        [SerializeField] private Material _extrudeMaterial;
        [Tooltip("Silhouette copies under the extrusion: outline (vertex colour = outline colour) - one continuous outline around the block.")]
        [SerializeField] private Material _silhouetteMaterial;
        [Tooltip("Back-most silhouette copy: outline + soft shadow below.")]
        [SerializeField] private Material _shadowMaterial;
        [Tooltip("Silhouette fill; match the materials' outline colour.")]
        [SerializeField] private Color _outlineColour = new Color(0.16f, 0.05f, 0.24f);

        [Header("Shape")]
        [SerializeField, Range(40f, 300f)] private float _topSize = 200f;
        [SerializeField, Range(40f, 300f)] private float _bottomSize = 176f;
        [Tooltip("Extrusion depth as a fraction of the font size, and how many stacked copies build it.")]
        [SerializeField, Range(0f, 0.3f)] private float _extrudeDepth = 0.11f;
        [SerializeField, Range(1, 24)] private int _extrudeLayers = 10;
        [Tooltip("Extra spacing between letters, fraction of the font size (negative = tighter).")]
        [SerializeField, Range(-0.2f, 0.2f)] private float _tracking = -0.02f;
        [Tooltip("Alternating tilt of the letters, degrees (playful, hand-set look).")]
        [SerializeField, Range(0f, 12f)] private float _tilt = 3f;

        [Header("Colours")]
        [SerializeField] private WordColours _top = new WordColours
        {
            FaceTop = new Color(1f, 0.96f, 0.45f), FaceBottom = new Color(1f, 0.62f, 0.05f),
            ExtrudeFront = new Color(0.93f, 0.36f, 0.05f), ExtrudeBack = new Color(0.62f, 0.13f, 0.08f),
        };
        [SerializeField] private WordColours _bottom = new WordColours
        {
            FaceTop = new Color(0.62f, 1f, 1f), FaceBottom = new Color(0.12f, 0.62f, 1f),
            ExtrudeFront = new Color(0.1f, 0.38f, 0.9f), ExtrudeBack = new Color(0.1f, 0.15f, 0.5f),
        };

        public TMP_FontAsset Font => _font;
        public Material FaceMaterial => _faceMaterial;
        public Material ExtrudeMaterial => _extrudeMaterial;
        public Material SilhouetteMaterial => _silhouetteMaterial;
        public Material ShadowMaterial => _shadowMaterial;
        public Color OutlineColour => _outlineColour;
        public float TopSize => _topSize;
        public float BottomSize => _bottomSize;
        public float ExtrudeDepth => _extrudeDepth;
        public int ExtrudeLayers => _extrudeLayers;
        public float Tracking => _tracking;
        public float Tilt => _tilt;
        public WordColours Top => _top;
        public WordColours Bottom => _bottom;
    }
}
